-- ----------------------------
-- Table structure for aps_load
-- ----------------------------
DROP TABLE IF EXISTS `aps_load`;
CREATE TABLE `aps_load`  (
  `id` bigint NOT NULL COMMENT '主键',
  `version_id` bigint NOT NULL COMMENT '排程版本编号',
  `res_id` bigint NOT NULL COMMENT '生产资源编号',
  `res_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源编码快照',
  `res_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源名称快照',
  `work_date` date NOT NULL COMMENT '负荷日期',
  `load_minutes` int NOT NULL COMMENT '计划负荷分钟数',
  `capacity_minutes` int NOT NULL COMMENT '可用产能分钟数',
  `load_rate` decimal(10, 4) NOT NULL COMMENT '负荷率',
  `overload_minutes` int NOT NULL DEFAULT 0 COMMENT '超负荷分钟数',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_load_res_day_deleted`(`version_id` ASC, `res_id` ASC, `work_date` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_load_overload`(`version_id` ASC, `overload_minutes` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-资源负荷' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_load
-- ----------------------------

-- ----------------------------
-- Table structure for aps_projection_inv
-- ----------------------------
DROP TABLE IF EXISTS `aps_projection_inv`;
CREATE TABLE `aps_projection_inv`  (
  `id` bigint NOT NULL COMMENT '主键',
  `scenario_id` bigint NOT NULL COMMENT '排程场景编号',
  `source_balance_id` bigint NOT NULL COMMENT 'WMS库存余额编号',
  `inv_org_id` bigint NOT NULL COMMENT '库存组织编号',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `wh_id` bigint NOT NULL COMMENT '仓库编号',
  `loc_id` bigint NOT NULL COMMENT '库位编号',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `batch_id` bigint NOT NULL COMMENT '批次编号',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '批次号快照',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `stock_scope` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库存范围：COMMON、PROJECT_DEDICATED',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质量状态',
  `qty_onhand` decimal(20, 6) NOT NULL COMMENT '现存数量快照',
  `qty_reserved` decimal(20, 6) NOT NULL COMMENT '预留数量快照',
  `qty_frozen` decimal(20, 6) NOT NULL COMMENT '冻结数量快照',
  `qty_available` decimal(20, 6) NOT NULL COMMENT '可用数量快照',
  `source_update_time` datetime NOT NULL COMMENT '来源数据更新时间',
  `snapshot_time` datetime NOT NULL COMMENT '投影快照时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_projection_inv_deleted`(`scenario_id` ASC, `source_balance_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_projection_inv_available`(`scenario_id` ASC, `mat_id` ASC, `quality_status` ASC, `project_id` ASC) USING BTREE,
  INDEX `idx_aps_projection_inv_batch`(`scenario_id` ASC, `batch_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-WMS库存投影' ROW_FORMAT = Dynamic;

