-- ----------------------------
-- Table structure for aps_projection_mat
-- ----------------------------
DROP TABLE IF EXISTS `aps_projection_mat`;
CREATE TABLE `aps_projection_mat`  (
  `id` bigint NOT NULL COMMENT '主键',
  `scenario_id` bigint NOT NULL COMMENT '排程场景编号',
  `source_mat_id` bigint NOT NULL COMMENT 'MDM物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物料规格快照',
  `mat_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料类型快照',
  `base_uom_id` bigint NOT NULL COMMENT '基准计量单位编号',
  `base_uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '基准计量单位编码快照',
  `batch_flag` bit(1) NOT NULL COMMENT '是否批次管控',
  `bom_id` bigint NOT NULL DEFAULT 0 COMMENT '当前有效BOM编号，0表示无',
  `bom_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前有效BOM版本',
  `route_id` bigint NOT NULL DEFAULT 0 COMMENT '当前有效工艺路线编号，0表示无',
  `route_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前有效工艺路线版本',
  `source_update_time` datetime NOT NULL COMMENT '来源数据更新时间',
  `snapshot_time` datetime NOT NULL COMMENT '投影快照时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_projection_mat_deleted`(`scenario_id` ASC, `source_mat_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_projection_mat_code`(`scenario_id` ASC, `mat_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-MDM物料投影' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_projection_mat
-- ----------------------------

-- ----------------------------
-- Table structure for aps_projection_order
-- ----------------------------
DROP TABLE IF EXISTS `aps_projection_order`;
CREATE TABLE `aps_projection_order`  (
  `id` bigint NOT NULL COMMENT '主键',
  `scenario_id` bigint NOT NULL COMMENT '排程场景编号',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源类型：DEMAND、PROD_ORDER、OP_TASK',
  `source_id` bigint NOT NULL COMMENT 'MES来源对象编号',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'MES来源对象单号',
  `prod_order_id` bigint NOT NULL DEFAULT 0 COMMENT '生产工单编号，0表示尚未生成工单',
  `work_order_id` bigint NOT NULL DEFAULT 0 COMMENT '作业工单编号，0表示尚未生成作业工单',
  `op_task_id` bigint NOT NULL DEFAULT 0 COMMENT '工序任务编号，0表示非工序投影',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `workshop_id` bigint NOT NULL DEFAULT 0 COMMENT '车间编号，0表示未指定',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `mat_id` bigint NOT NULL COMMENT '生产物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `route_op_id` bigint NOT NULL DEFAULT 0 COMMENT '路线工序编号，0表示需求或整单',
  `op_id` bigint NOT NULL DEFAULT 0 COMMENT '标准工序编号，0表示非工序投影；求解时按它匹配资源能力',
  `op_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '工序编码快照',
  `op_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '工序名称快照',
  `seq` int NOT NULL DEFAULT 0 COMMENT '工序在路线中的顺序号，0表示非工序投影',
  `res_id` bigint NOT NULL DEFAULT 0 COMMENT '当前资源编号，0表示未分配',
  `qty` decimal(20, 6) NOT NULL COMMENT '计划数量或剩余数量',
  `completed_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已完成数量快照',
  `due_date` datetime NOT NULL COMMENT '交期',
  `priority` int NOT NULL DEFAULT 0 COMMENT '优先级',
  `setup_minutes` int NOT NULL DEFAULT 0 COMMENT '准备换型工时，路线工序override优先回落标准工序',
  `std_minutes_per_unit` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '单件加工工时',
  `teardown_minutes` int NOT NULL DEFAULT 0 COMMENT '收尾工时',
  `queue_minutes` int NOT NULL DEFAULT 0 COMMENT '排队等待分钟数，只作工序间隔不占资源',
  `move_minutes` int NOT NULL DEFAULT 0 COMMENT '转移分钟数，只作工序间隔不占资源',
  `duration_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PER_UNIT' COMMENT '工时类型：FIXED固定工时、PER_UNIT按件累加',
  `std_duration` int NOT NULL DEFAULT 0 COMMENT '固定工时分钟数，duration_type为FIXED时取用',
  `man_qty` int NOT NULL DEFAULT 1 COMMENT '标准人数',
  `changeover_group` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物料换型分组快照，空表示不参与换型计算',
  `material_shortage_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否缺料，由BOM展开对冲库存投影得出',
  `material_short_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '缺料数量合计，多种子件缺料时累加',
  `current_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源对象状态快照',
  `actual_start_time` datetime NULL DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime NULL DEFAULT NULL COMMENT '实际结束时间',
  `locked_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已开工或业务锁定',
  `source_update_time` datetime NOT NULL COMMENT '来源数据更新时间',
  `snapshot_time` datetime NOT NULL COMMENT '投影快照时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_projection_order_deleted`(`scenario_id` ASC, `source_type` ASC, `source_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_projection_order_due`(`scenario_id` ASC, `current_status` ASC, `due_date` ASC) USING BTREE,
  INDEX `idx_aps_projection_order_project`(`scenario_id` ASC, `project_id` ASC, `project_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-MES需求工单任务投影' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_projection_order
-- ----------------------------

-- ----------------------------
-- Table structure for aps_projection_resource
-- ----------------------------
DROP TABLE IF EXISTS `aps_projection_resource`;
CREATE TABLE `aps_projection_resource`  (
  `id` bigint NOT NULL COMMENT '主键',
  `scenario_id` bigint NOT NULL COMMENT '排程场景编号',
  `source_res_id` bigint NOT NULL COMMENT 'MDM生产资源编号',
  `res_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源编码快照',
  `res_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源名称快照',
  `res_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源类型快照',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `workshop_id` bigint NOT NULL COMMENT '车间编号',
  `wc_id` bigint NOT NULL COMMENT '工作中心编号',
  `work_date` date NOT NULL COMMENT '产能日期',
  `shift_id` bigint NOT NULL DEFAULT 0 COMMENT '班次编号，0表示日汇总',
  `shift_start_time` time NULL DEFAULT NULL COMMENT '班次开始时间，日汇总记录为空',
  `shift_end_time` time NULL DEFAULT NULL COMMENT '班次结束时间，日汇总记录为空',
  `available_minutes` int NOT NULL COMMENT '可用分钟数',
  `capability_json` json NULL COMMENT '资源能力快照',
  `source_update_time` datetime NOT NULL COMMENT '来源数据更新时间',
  `snapshot_time` datetime NOT NULL COMMENT '投影快照时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_projection_res_day_deleted`(`scenario_id` ASC, `source_res_id` ASC, `work_date` ASC, `shift_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_projection_res_wc`(`scenario_id` ASC, `wc_id` ASC, `work_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-MDM资源与日历投影' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_projection_resource
-- ----------------------------

-- ----------------------------
-- Table structure for aps_scenario
-- ----------------------------
DROP TABLE IF EXISTS `aps_scenario`;
CREATE TABLE `aps_scenario`  (
  `id` bigint NOT NULL COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '排程场景编码',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '排程场景名称',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `workshop_id` bigint NOT NULL DEFAULT 0 COMMENT '车间编号，0表示全工厂',
  `strategy_id` bigint NOT NULL COMMENT '排程策略编号',
  `plan_start_time` datetime NOT NULL COMMENT '计划窗口开始时间',
  `plan_end_time` datetime NOT NULL COMMENT '计划窗口结束时间',
  `snapshot_time` datetime NULL DEFAULT NULL COMMENT '输入数据快照时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、SNAPSHOTTING、READY、SOLVING、SOLVED、CLOSED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_scenario_code_deleted`(`code` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_scenario_plant_status`(`plant_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_aps_scenario_plan_window`(`plan_start_time` ASC, `plan_end_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-排程场景' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_scenario
-- ----------------------------

-- ----------------------------
-- Table structure for aps_shortage
-- ----------------------------
DROP TABLE IF EXISTS `aps_shortage`;
CREATE TABLE `aps_shortage`  (
  `id` bigint NOT NULL COMMENT '主键',
  `version_id` bigint NOT NULL COMMENT '排程版本编号',
  `prod_order_id` bigint NOT NULL DEFAULT 0 COMMENT '生产工单编号，0表示汇总缺料',
  `op_task_id` bigint NOT NULL DEFAULT 0 COMMENT '工序任务编号，0表示非工序级缺料',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `mat_id` bigint NOT NULL COMMENT '短缺物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `req_qty` decimal(20, 6) NOT NULL COMMENT '需求数量',
  `avail_qty` decimal(20, 6) NOT NULL COMMENT '可用数量',
  `short_qty` decimal(20, 6) NOT NULL COMMENT '短缺数量',
  `uom_id` bigint NOT NULL COMMENT '计量单位编号',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '计量单位编码快照',
  `need_date` datetime NOT NULL COMMENT '需求到位时间',
  `expected_supply_date` datetime NULL DEFAULT NULL COMMENT '预计供给时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：OPEN、PARTIAL、RESOLVED、IGNORED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_aps_shortage_version_mat`(`version_id` ASC, `mat_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_aps_shortage_need_date`(`version_id` ASC, `need_date` ASC) USING BTREE,
  INDEX `idx_aps_shortage_project`(`project_id` ASC, `project_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-排程缺料清单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_shortage
-- ----------------------------

-- ----------------------------
-- Table structure for aps_solver_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `aps_solver_snapshot`;
CREATE TABLE `aps_solver_snapshot`  (
  `id` bigint NOT NULL COMMENT '主键',
  `version_id` bigint NOT NULL COMMENT '排程版本编号',
  `snapshot_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快照类型：INPUT、SOLUTION、CONSTRAINT_MATCH、ERROR',
  `snapshot_json` json NOT NULL COMMENT 'Timefold求解输入、结果或约束命中快照',
  `checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快照内容校验值',
  `snapshot_time` datetime NOT NULL COMMENT '快照生成时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_solver_snapshot_deleted`(`version_id` ASC, `snapshot_type` ASC, `checksum` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_solver_snapshot_time`(`version_id` ASC, `snapshot_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-Timefold求解快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_solver_snapshot
-- ----------------------------

-- ----------------------------
-- Table structure for aps_strategy
-- ----------------------------
DROP TABLE IF EXISTS `aps_strategy`;
CREATE TABLE `aps_strategy`  (
  `id` bigint NOT NULL COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '排程策略编码',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '排程策略名称',
  `version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '策略版本号',
  `objective` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优化目标说明',
  `config_json` json NOT NULL COMMENT '硬约束、软约束及权重配置',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、ENABLED、DISABLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_strategy_code_ver_deleted`(`code` ASC, `version_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_strategy_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-排程策略' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_strategy
-- ----------------------------

-- ----------------------------
-- Table structure for aps_task
-- ----------------------------
DROP TABLE IF EXISTS `aps_task`;
CREATE TABLE `aps_task`  (
  `id` bigint NOT NULL COMMENT '主键',
  `version_id` bigint NOT NULL COMMENT '排程版本编号',
  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '排程任务编号',
  `prod_order_id` bigint NOT NULL COMMENT '生产工单编号',
  `prod_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '生产工单号快照',
  `work_order_id` bigint NOT NULL COMMENT '作业工单编号',
  `op_task_id` bigint NOT NULL COMMENT 'MES工序任务编号',
  `route_op_id` bigint NOT NULL COMMENT '路线工序编号',
  `op_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工序编码快照',
  `op_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工序名称快照',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `workshop_id` bigint NOT NULL COMMENT '车间编号',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `res_id` bigint NOT NULL COMMENT '排定生产资源编号',
  `res_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源编码快照',
  `start_time` datetime NOT NULL COMMENT '计划开始时间',
  `end_time` datetime NOT NULL COMMENT '计划结束时间',
  `duration_minutes` int NOT NULL COMMENT '计划占用分钟数',
  `changeover_minutes` int NOT NULL DEFAULT 0 COMMENT '本次换型损失分钟数，已含在占用分钟内',
  `sequence_no` int NOT NULL COMMENT '资源内执行顺序号',
  `locked_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否锁定不可移动',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：PLANNED、LOCKED、RELEASED、STARTED、DONE、CANCELLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_task_version_op_deleted`(`version_id` ASC, `op_task_id` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_aps_task_no_deleted`(`task_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_task_resource_time`(`version_id` ASC, `res_id` ASC, `start_time` ASC) USING BTREE,
  INDEX `idx_aps_task_order`(`version_id` ASC, `prod_order_id` ASC, `sequence_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-工序排程任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_task
-- ----------------------------

-- ----------------------------
-- Table structure for aps_task_dep
-- ----------------------------
DROP TABLE IF EXISTS `aps_task_dep`;
CREATE TABLE `aps_task_dep`  (
  `id` bigint NOT NULL COMMENT '主键',
  `version_id` bigint NOT NULL COMMENT '排程版本编号',
  `from_task_id` bigint NOT NULL COMMENT '前置排程任务编号',
  `to_task_id` bigint NOT NULL COMMENT '后置排程任务编号',
  `dep_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '依赖类型：FINISH_START、START_START、FINISH_FINISH',
  `lag_minutes` int NOT NULL DEFAULT 0 COMMENT '依赖间隔分钟数',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_task_dep_deleted`(`version_id` ASC, `from_task_id` ASC, `to_task_id` ASC, `dep_type` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_task_dep_to`(`version_id` ASC, `to_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-排程任务依赖' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_task_dep
-- ----------------------------

-- ----------------------------
-- Table structure for aps_task_lock
-- ----------------------------
DROP TABLE IF EXISTS `aps_task_lock`;
CREATE TABLE `aps_task_lock`  (
  `id` bigint NOT NULL COMMENT '主键',
  `task_id` bigint NOT NULL COMMENT '排程任务编号',
  `lock_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '锁定类型：STARTED、MANUAL、MATERIAL、RESOURCE',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '锁定原因',
  `locked_by` bigint NULL DEFAULT NULL COMMENT '锁定人员编号',
  `locked_time` datetime NOT NULL COMMENT '锁定时间',
  `unlock_time` datetime NULL DEFAULT NULL COMMENT '解锁时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：LOCKED、UNLOCKED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_aps_task_lock_task`(`task_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_aps_task_lock_time`(`locked_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-排程任务锁定记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_task_lock
-- ----------------------------

-- ----------------------------
-- Table structure for aps_version
-- ----------------------------
DROP TABLE IF EXISTS `aps_version`;
CREATE TABLE `aps_version`  (
  `id` bigint NOT NULL COMMENT '主键',
  `scenario_id` bigint NOT NULL COMMENT '排程场景编号',
  `version_no` int NOT NULL COMMENT '排程版本号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：SOLVING、SOLVED、PENDING_CONFIRM、PUBLISHED、REPLACED、FAILED',
  `score` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Timefold综合得分',
  `hard_score` bigint NULL DEFAULT NULL COMMENT '硬约束得分',
  `soft_score` bigint NULL DEFAULT NULL COMMENT '软约束得分',
  `solve_start_time` datetime NULL DEFAULT NULL COMMENT '求解开始时间',
  `solve_end_time` datetime NULL DEFAULT NULL COMMENT '求解结束时间',
  `published_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `published_by` bigint NULL DEFAULT NULL COMMENT '发布人员编号',
  `solver_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '求解结果或失败信息',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_aps_version_scenario_no_deleted`(`scenario_id` ASC, `version_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_aps_version_status`(`scenario_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'APS-排程版本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aps_version
-- ----------------------------

