-- ----------------------------
-- Table structure for infra_code_rule
-- ----------------------------
DROP TABLE IF EXISTS `infra_code_rule`;
CREATE TABLE `infra_code_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则名称',
  `prefix` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '前缀',
  `year_enabled` tinyint NOT NULL DEFAULT 0 COMMENT '是否包含年',
  `month_enabled` tinyint NOT NULL DEFAULT 0 COMMENT '是否包含月',
  `day_enabled` tinyint NOT NULL DEFAULT 0 COMMENT '是否包含日',
  `suffix` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '后缀',
  `serial_length` int NOT NULL COMMENT '流水号长度',
  `serial_start` bigint NOT NULL COMMENT '流水号起始值',
  `serial_step` bigint NOT NULL COMMENT '流水号步长',
  `reset_cycle` tinyint NOT NULL DEFAULT 0 COMMENT '重置周期：0不重置，1按年，2按月，3按日',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0开启，1关闭',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rule_code_deleted`(`rule_code` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '编码规则表' ROW_FORMAT = Dynamic;

