-- Table structure for mdm_bom_line
-- ----------------------------
DROP TABLE IF EXISTS `mdm_bom_line`;
CREATE TABLE `mdm_bom_line`  (
  `id` bigint NOT NULL COMMENT '主键',
  `bom_id` bigint NOT NULL COMMENT 'BOM编号',
  `line_no` int NOT NULL COMMENT '行号',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `qty` decimal(18, 6) NOT NULL COMMENT '数量',
  `scrap_rate` decimal(8, 6) NOT NULL DEFAULT 0.000000 COMMENT '损耗率',
  `issue_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PICK' COMMENT '供料方式：PICK-领料，BACKFLUSH-倒冲，PHANTOM-虚拟件，DIRECT-直送线边',
  `route_op_seq` int NULL DEFAULT NULL COMMENT '用料绑定工序顺序号',
  `position_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '位号/装配位置',
  `effective_date` date NULL DEFAULT NULL COMMENT '行级生效日期',
  `expiry_date` date NULL DEFAULT NULL COMMENT '行级失效日期',
  `uom_id` bigint NOT NULL COMMENT '计量单位编号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mdm_bom_line_bom_line_deleted`(`bom_id` ASC, `line_no` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MDM-BOM行' ROW_FORMAT = Dynamic;

