  `safety_stock` decimal(20, 6) NULL DEFAULT NULL COMMENT '安全库存',
  `min_order_qty` decimal(20, 6) NULL DEFAULT NULL COMMENT '最小订货量',
  `order_multiple` decimal(20, 6) NULL DEFAULT NULL COMMENT '订货倍数',
