  `override_std_minutes_per_unit` decimal(18, 6) NULL DEFAULT NULL COMMENT '覆盖单件加工工时（分钟），为空继承标准工序',
  `override_queue_minutes` int NULL DEFAULT NULL COMMENT '覆盖排队等待时间（分钟），为空继承标准工序',
  `override_move_minutes` int NULL DEFAULT NULL COMMENT '覆盖转移时间（分钟），为空继承标准工序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
