-- ----------------------------
-- Table structure for mes_command_record
-- ----------------------------
DROP TABLE IF EXISTS `mes_command_record`;
CREATE TABLE `mes_command_record`  (
  `id` bigint NOT NULL COMMENT '编号',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '幂等键，格式 sourceModule:sourceBizNo:action:sourceBizLineNo',
  `command_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '命令类型，取值见 MesCommandTypeEnum',
  `source_module` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源模块：MES、APS、WMS、INTEGRATION、UI',
  `source_biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `source_biz_line_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源业务行号，整单命令为空',
  `result_id` bigint NULL DEFAULT NULL COMMENT '首次执行的结果编号，无返回值的命令为空',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_command_idempotency_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-跨模块命令幂等记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mes_command_record
-- ----------------------------

-- ----------------------------
-- Table structure for mes_defect
-- ----------------------------
DROP TABLE IF EXISTS `mes_defect`;
CREATE TABLE `mes_defect`  (
  `id` bigint NOT NULL COMMENT '主键',
  `task_id` bigint NOT NULL COMMENT '质检任务编号',
  `result_id` bigint NULL DEFAULT NULL COMMENT '关联检验结果编号',
  `defect_code_id` bigint NOT NULL DEFAULT 0 COMMENT '缺陷代码编号，来自 mdm_defect_code',
  `defect_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '缺陷编码',
  `defect_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '缺陷名称',
  `defect_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缺陷等级：CRITICAL、MAJOR、MINOR',
  `qty` decimal(20, 6) NOT NULL COMMENT '缺陷数量',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缺陷描述',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缺陷位置',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_mes_defect_task`(`task_id` ASC, `defect_code` ASC) USING BTREE,
  INDEX `idx_mes_defect_result`(`result_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-缺陷记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mes_defect
-- ----------------------------

-- ----------------------------
-- Table structure for mes_defect_file
-- ----------------------------
DROP TABLE IF EXISTS `mes_defect_file`;
CREATE TABLE `mes_defect_file`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `defect_id` bigint NOT NULL COMMENT '缺陷记录编号',
  `seq` int NOT NULL COMMENT '附件展示顺序',
  `file_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件类型：IMAGE、VIDEO、PDF、DRAWING、OFFICE、OTHER',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原始文件名',
  `file_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件地址，存去签名地址',
  `file_id` bigint NULL DEFAULT NULL COMMENT 'infra 文件编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_mes_defect_file_defect_id`(`defect_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-缺陷记录附件' ROW_FORMAT = Dynamic;

