DROP TABLE IF EXISTS `mes_dispatch_task`;
CREATE TABLE `mes_dispatch_task`  (
  `id` bigint NOT NULL COMMENT '主键',
  `dispatch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '派工单号',
  `op_task_id` bigint NOT NULL COMMENT '工序任务编号',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '作业人员编号',
  `team_id` bigint NULL DEFAULT NULL COMMENT '作业班组编号',
  `res_id` bigint NOT NULL COMMENT '生产资源编号',
  `shift_id` bigint NULL DEFAULT NULL COMMENT '班次编号',
  `planned_start_time` datetime NULL DEFAULT NULL COMMENT '计划开始时间',
  `planned_end_time` datetime NULL DEFAULT NULL COMMENT '计划结束时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：PENDING、ACCEPTED、RUNNING、DONE、CANCELLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_dispatch_no_deleted`(`dispatch_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_dispatch_task`(`op_task_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_mes_dispatch_operator`(`operator_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-派工任务' ROW_FORMAT = Dynamic;

