  INDEX `idx_mes_disposition_task`(`task_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_mes_disposition_target`(`target_biz_type` ASC, `target_biz_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-不合格品处置单' ROW_FORMAT = Dynamic;

