-- ----------------------------
-- Table structure for mes_kit_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `mes_kit_snapshot`;
CREATE TABLE `mes_kit_snapshot`  (
  `id` bigint NOT NULL COMMENT '主键',
  `check_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '齐套检查编号',
  `check_scope` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检查范围：PROD_ORDER、WORK_ORDER、OP_TASK',
  `prod_order_id` bigint NOT NULL COMMENT '生产工单编号',
  `work_order_id` bigint NOT NULL DEFAULT 0 COMMENT '作业工单编号，0表示整单检查',
  `op_task_id` bigint NOT NULL DEFAULT 0 COMMENT '工序任务编号，0表示非工序检查',
  `line_no` int NOT NULL COMMENT '检查明细行号',
  `mat_id` bigint NOT NULL COMMENT '需求物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `req_qty` decimal(20, 6) NOT NULL COMMENT '需求数量',
  `avail_qty` decimal(20, 6) NOT NULL COMMENT '检查时可用数量',
  `reserved_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '检查时本需求已预留数量',
  `issued_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '检查时已领用数量',
  `short_qty` decimal(20, 6) NOT NULL COMMENT '短缺数量',
  `alt_mat_id` bigint NOT NULL DEFAULT 0 COMMENT '实际采用替代料编号，0表示未采用',
  `result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检查结果：FULL_KIT、PARTIAL_KIT、SHORTAGE',
  `check_time` datetime NOT NULL COMMENT '检查时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_kit_snapshot_line_deleted`(`check_no` ASC, `line_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_kit_snapshot_prod`(`prod_order_id` ASC, `check_time` ASC) USING BTREE,
  INDEX `idx_mes_kit_snapshot_op`(`op_task_id` ASC, `check_time` ASC) USING BTREE,
  INDEX `idx_mes_kit_snapshot_mat`(`mat_id` ASC, `result` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-齐套检查快照' ROW_FORMAT = Dynamic;

