-- ----------------------------
-- Table structure for mes_op_skip_record
-- ----------------------------
DROP TABLE IF EXISTS `mes_op_skip_record`;
CREATE TABLE `mes_op_skip_record`  (
  `id` bigint NOT NULL COMMENT '主键',
  `op_task_id` bigint NOT NULL COMMENT '被跳过工序任务编号',
  `skip_reason_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '跳过原因类型',
  `skip_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '跳过原因',
  `operator_id` bigint NOT NULL COMMENT '操作人员编号',
  `approved_by` bigint NULL DEFAULT NULL COMMENT '审批人员编号',
  `approve_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '审批状态：NOT_REQUIRED、PENDING、APPROVED、REJECTED',
  `skip_time` datetime NULL DEFAULT NULL COMMENT '实际跳过时间',
  `effect_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '对后续工序、质检及排程的影响说明',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：PENDING、EFFECTIVE、REVOKED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_mes_op_skip_task`(`op_task_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_mes_op_skip_approve`(`approve_status` ASC, `approved_by` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-工序跳过记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mes_op_skip_record
-- ----------------------------

-- ----------------------------
-- Table structure for mes_op_task
-- ----------------------------
DROP TABLE IF EXISTS `mes_op_task`;
CREATE TABLE `mes_op_task`  (
  `id` bigint NOT NULL COMMENT '主键',
  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工序任务号',
  `work_order_id` bigint NOT NULL COMMENT '作业工单编号',
  `work_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '作业工单号快照',
  `route_op_id` bigint NOT NULL COMMENT '锁定的路线工序编号',
  `op_id` bigint NOT NULL COMMENT '标准工序编号',
  `op_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工序编码快照',
  `op_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工序名称快照',
  `seq` int NOT NULL COMMENT '工序顺序号',
  `parallel_group` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '并行工序组',
  `prev_task_id` bigint NULL DEFAULT NULL COMMENT '前序工序任务编号',
  `next_task_id` bigint NULL DEFAULT NULL COMMENT '后序工序任务编号',
  `exec_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'SEQUENTIAL' COMMENT '执行模式：SEQUENTIAL、PARALLEL、OPTIONAL',
  `qc_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT '质检模式：NONE、BEFORE_START、FIRST_ARTICLE、PROCESS、BEFORE_COMPLETE',
  `skip_policy` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NOT_ALLOWED' COMMENT '跳序策略：NOT_ALLOWED、ALLOW_WITH_REASON、APPROVAL_REQUIRED',
  `key_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否关键工序',
  `planned_qty` decimal(20, 6) NOT NULL COMMENT '计划数量',
  `completed_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '合格完成数量',
  `scrap_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '报废数量',
  `res_id` bigint NULL DEFAULT NULL COMMENT '当前分配资源编号',
  `planned_start_time` datetime NULL DEFAULT NULL COMMENT '计划开始时间',
  `planned_end_time` datetime NULL DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime NULL DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime NULL DEFAULT NULL COMMENT '实际结束时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：PENDING、READY、RUNNING、PAUSED、QC_WAITING、HOLD、DONE、SKIPPED、CANCELLED',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_op_task_no_deleted`(`task_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_mes_op_task_route_deleted`(`work_order_id` ASC, `route_op_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_op_task_status_plan`(`status` ASC, `planned_start_time` ASC) USING BTREE,
  INDEX `idx_mes_op_task_res`(`res_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-工序任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mes_op_task
-- ----------------------------

