-- ----------------------------
-- Table structure for mes_prod_order
-- ----------------------------
DROP TABLE IF EXISTS `mes_prod_order`;
CREATE TABLE `mes_prod_order`  (
  `id` bigint NOT NULL COMMENT '主键',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '生产工单号',
  `demand_id` bigint NULL DEFAULT NULL COMMENT '生产需求编号',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `workshop_id` bigint NOT NULL COMMENT '车间编号',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `mat_id` bigint NOT NULL COMMENT '生产物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物料规格快照',
  `qty` decimal(20, 6) NOT NULL COMMENT '计划生产数量',
  `completed_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已完成数量',
  `scrap_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '累计报废数量',
  `uom_id` bigint NOT NULL COMMENT '计量单位编号',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '计量单位编码快照',
  `bom_id` bigint NOT NULL COMMENT '锁定的BOM编号',
  `bom_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '锁定的BOM版本',
  `route_id` bigint NOT NULL COMMENT '锁定的工艺路线编号',
  `route_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '锁定的工艺路线版本',
  `due_date` datetime NOT NULL COMMENT '工单交期',
  `priority` int NOT NULL DEFAULT 0 COMMENT '优先级',
  `kit_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNCHECKED' COMMENT '齐套状态：UNCHECKED、FULL_KIT、PARTIAL_KIT、SHORTAGE',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、RELEASED、READY、RUNNING、HOLD、DONE、CLOSED、CANCELLED',
  `release_time` datetime NULL DEFAULT NULL COMMENT '下达时间',
  `actual_start_time` datetime NULL DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime NULL DEFAULT NULL COMMENT '实际结束时间',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_prod_order_no_deleted`(`order_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_prod_order_demand`(`demand_id` ASC) USING BTREE,
  INDEX `idx_mes_prod_order_status_due`(`plant_id` ASC, `status` ASC, `due_date` ASC) USING BTREE,
  INDEX `idx_mes_prod_order_project`(`project_id` ASC, `project_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-生产工单' ROW_FORMAT = Dynamic;

