-- Records of mes_prod_order
-- ----------------------------

-- ----------------------------
-- Table structure for mes_prod_report
-- ----------------------------
DROP TABLE IF EXISTS `mes_prod_report`;
CREATE TABLE `mes_prod_report`  (
  `id` bigint NOT NULL COMMENT '主键',
  `report_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '报工单号',
  `prod_order_id` bigint NOT NULL COMMENT '生产工单编号',
  `work_order_id` bigint NOT NULL COMMENT '作业工单编号',
  `op_task_id` bigint NOT NULL COMMENT '工序任务编号',
  `worker_id` bigint NULL DEFAULT NULL COMMENT '报工作业人员编号',
  `res_id` bigint NOT NULL COMMENT '生产资源编号',
  `shift_id` bigint NULL DEFAULT NULL COMMENT '班次编号',
  `qty_good` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '合格数量',
  `qty_scrap` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '报废数量',
  `qty_rework` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '返工数量',
  `start_time` datetime NOT NULL COMMENT '本次作业开始时间',
  `end_time` datetime NOT NULL COMMENT '本次作业结束时间',
  `report_time` datetime NOT NULL COMMENT '报工时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、SUBMITTED、QC_PENDING、CONFIRMED、CANCELLED',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '报工幂等键',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_prod_report_no_deleted`(`report_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_mes_prod_report_idem_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_prod_report_op_time`(`op_task_id` ASC, `report_time` ASC) USING BTREE,
  INDEX `idx_mes_prod_report_order`(`prod_order_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-生产报工记录' ROW_FORMAT = Dynamic;

