-- Table structure for mes_qc_item
-- ----------------------------
DROP TABLE IF EXISTS `mes_qc_item`;
CREATE TABLE `mes_qc_item`  (
  `id` bigint NOT NULL COMMENT '主键',
  `plan_id` bigint NOT NULL COMMENT '检验方案编号',
  `item_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验项编码',
  `item_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验项名称',
  `item_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验项类型：NUMERIC、TEXT、BOOLEAN',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '检验值单位',
  `std_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标准值',
  `upper_limit` decimal(20, 6) NULL DEFAULT NULL COMMENT '数值上限',
  `lower_limit` decimal(20, 6) NULL DEFAULT NULL COMMENT '数值下限',
  `required_flag` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否必检',
  `sort_no` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-启用，1-停用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_qc_item_code_deleted`(`plan_id` ASC, `item_code` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_qc_item_sort`(`plan_id` ASC, `sort_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-检验项目' ROW_FORMAT = Dynamic;

