-- ----------------------------
-- Table structure for mes_qc_result
-- ----------------------------
DROP TABLE IF EXISTS `mes_qc_result`;
CREATE TABLE `mes_qc_result`  (
  `id` bigint NOT NULL COMMENT '主键',
  `task_id` bigint NOT NULL COMMENT '质检任务编号',
  `item_id` bigint NOT NULL COMMENT '检验项目编号',
  `sample_no` int NOT NULL DEFAULT 1 COMMENT '样本序号',
  `item_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验项编码快照',
  `item_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验项名称快照',
  `actual_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '实测值',
  `pass_flag` bit(1) NOT NULL COMMENT '是否合格',
  `inspector_id` bigint NOT NULL COMMENT '检验员编号',
  `inspect_time` datetime NOT NULL COMMENT '检验时间',
  `qty_qualified` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '本项判定合格数量',
  `qty_rejected` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '本项判定不合格数量',
  `conclusion` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '项目结论：PASS、FAIL',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_qc_result_sample_deleted`(`task_id` ASC, `item_id` ASC, `sample_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_qc_result_task_pass`(`task_id` ASC, `pass_flag` ASC) USING BTREE,
  INDEX `idx_mes_qc_result_inspector`(`inspector_id` ASC, `inspect_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-检验结果' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mes_qc_result
-- ----------------------------

-- ----------------------------
-- Table structure for mes_qc_rule
-- ----------------------------
DROP TABLE IF EXISTS `mes_qc_rule`;
CREATE TABLE `mes_qc_rule`  (
  `id` bigint NOT NULL COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质检规则编码',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质检规则名称',
  `trigger_point` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发点：IQC、IPQC、FQC、OQC、FAI',
  `object_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验对象类型：MATERIAL、BATCH、OP_TASK、PROD_ORDER、OUT_ORDER',
  `mat_id` bigint NOT NULL DEFAULT 0 COMMENT '指定物料编号，0表示不限',
  `mat_cat_id` bigint NOT NULL DEFAULT 0 COMMENT '指定物料分类编号，0表示不限',
  `op_id` bigint NOT NULL DEFAULT 0 COMMENT '指定工序编号，0表示不限',
  `wc_id` bigint NOT NULL DEFAULT 0 COMMENT '指定工作中心编号，0表示不限',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '指定供应商编号，0表示不限',
  `qc_plan_id` bigint NOT NULL COMMENT '检验方案编号',
  `qc_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '检验模式：PRE_INBOUND、POST_INBOUND_PENDING、BEFORE_START、FIRST_ARTICLE、PROCESS、BEFORE_COMPLETE',
  `priority` int NOT NULL DEFAULT 0 COMMENT '优先级，数值越大越优先',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-启用，1-停用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_qc_rule_code_deleted`(`code` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_qc_rule_match`(`trigger_point` ASC, `object_type` ASC, `status` ASC, `priority` ASC) USING BTREE,
  INDEX `idx_mes_qc_rule_mat`(`mat_id` ASC, `mat_cat_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-质检触发规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mes_qc_rule
-- ----------------------------

-- ----------------------------
-- Table structure for mes_qc_task
-- ----------------------------
DROP TABLE IF EXISTS `mes_qc_task`;
CREATE TABLE `mes_qc_task`  (
  `id` bigint NOT NULL COMMENT '主键',
  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质检任务号',
  `rule_id` bigint NULL DEFAULT NULL COMMENT '命中的质检规则编号',
  `qc_plan_id` bigint NOT NULL COMMENT '锁定的检验方案编号',
  `qc_plan_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '锁定的检验方案版本',
  `trigger_point` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发点：IQC、IPQC、FQC、OQC、FAI',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务类型',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `biz_line_id` bigint NULL DEFAULT NULL COMMENT '来源业务明细编号',
  `mat_id` bigint NOT NULL COMMENT '检验物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物料规格快照',
  `batch_id` bigint NULL DEFAULT NULL COMMENT '检验批次编号',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '批次号快照',
  `qty` decimal(20, 6) NOT NULL COMMENT '送检数量',
  `sample_qty` decimal(20, 6) NOT NULL COMMENT '抽样数量',
  `uom_id` bigint NOT NULL COMMENT '计量单位编号',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '计量单位编码快照',
  `assigned_inspector_id` bigint NULL DEFAULT NULL COMMENT '指派检验员编号',
  `inspect_start_time` datetime NULL DEFAULT NULL COMMENT '检验开始时间',
  `inspect_end_time` datetime NULL DEFAULT NULL COMMENT '检验结束时间',
  `conclusion` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '检验结论：QUALIFIED、REJECTED、CONCESSION',
  `qty_qualified` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '合格数量',
  `qty_rejected` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '不合格数量',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：CREATED、ASSIGNED、INSPECTING、RESULT_POSTING、DONE、CANCELLED',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建幂等键',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_qc_task_no_deleted`(`task_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_mes_qc_task_idem_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_qc_task_biz`(`biz_type` ASC, `biz_no` ASC) USING BTREE,
  INDEX `idx_mes_qc_task_mat_batch`(`mat_id` ASC, `batch_id` ASC) USING BTREE,
  INDEX `idx_mes_qc_task_status`(`trigger_point` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-质检任务' ROW_FORMAT = Dynamic;

