  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务幂等键',
  `completed_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
