-- ----------------------------
-- Table structure for mes_wip_txn
-- ----------------------------
DROP TABLE IF EXISTS `mes_wip_txn`;
CREATE TABLE `mes_wip_txn`  (
  `id` bigint NOT NULL COMMENT '主键',
  `txn_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '在制事务编号',
  `prod_order_id` bigint NOT NULL COMMENT '生产工单编号',
  `work_order_id` bigint NOT NULL COMMENT '作业工单编号',
  `op_task_id` bigint NOT NULL COMMENT '工序任务编号',
  `txn_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事务类型：START、PAUSE、RESUME、REPORT、MOVE、SKIP、COMPLETE、REWORK、SCRAP',
  `qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '事务数量',
  `from_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更前状态',
  `to_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '变更后状态',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务类型',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `from_op_task_id` bigint NOT NULL DEFAULT 0 COMMENT '来源工序任务编号，0表示无',
  `to_op_task_id` bigint NOT NULL DEFAULT 0 COMMENT '目标工序任务编号，0表示无',
  `txn_time` datetime NOT NULL COMMENT '事务发生时间',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事务幂等键',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_wip_txn_no_deleted`(`txn_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_mes_wip_txn_idem_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_wip_txn_op_time`(`op_task_id` ASC, `txn_time` ASC) USING BTREE,
  INDEX `idx_mes_wip_txn_biz`(`biz_type` ASC, `biz_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-在制流转流水' ROW_FORMAT = Dynamic;

