-- ----------------------------
-- Table structure for mes_work_order
-- ----------------------------
DROP TABLE IF EXISTS `mes_work_order`;
CREATE TABLE `mes_work_order`  (
  `id` bigint NOT NULL COMMENT '主键',
  `work_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '作业工单号',
  `prod_order_id` bigint NOT NULL COMMENT '生产工单编号',
  `prod_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '生产工单号快照',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `workshop_id` bigint NOT NULL COMMENT '车间编号',
  `wc_id` bigint NOT NULL COMMENT '工作中心编号',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `planned_qty` decimal(20, 6) NOT NULL COMMENT '计划数量',
  `completed_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已完成数量',
  `planned_start_time` datetime NULL DEFAULT NULL COMMENT '计划开始时间',
  `planned_end_time` datetime NULL DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime NULL DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime NULL DEFAULT NULL COMMENT '实际结束时间',
  `kit_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNCHECKED' COMMENT '齐套状态',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：PENDING、READY、RUNNING、HOLD、DONE、CANCELLED',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mes_work_order_no_deleted`(`work_order_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mes_work_order_prod`(`prod_order_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_mes_work_order_workshop`(`workshop_id` ASC, `wc_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MES-作业工单' ROW_FORMAT = Dynamic;

