-- ----------------------------
-- Table structure for system_users
-- ----------------------------
DROP TABLE IF EXISTS `system_users`;
CREATE TABLE `system_users`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户账号',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '密码',
  `nickname` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户昵称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门ID',
  `post_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '岗位编号数组',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '用户邮箱',
  `mobile` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '手机号码',
  `sex` tinyint NULL DEFAULT 0 COMMENT '用户性别',
  `avatar` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '头像地址',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '帐号状态（0正常 1停用）',
  `login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '最后登录IP',
  `login_date` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_username`(`username` ASC) USING BTREE,
  INDEX `idx_mobile`(`mobile` ASC) USING BTREE,
  INDEX `idx_email`(`email` ASC) USING BTREE,
  INDEX `idx_dept_id`(`dept_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 249 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of system_users
-- ----------------------------

-- ----------------------------
-- Table structure for wms_arrival
-- ----------------------------
DROP TABLE IF EXISTS `wms_arrival`;
CREATE TABLE `wms_arrival`  (
  `id` bigint NOT NULL COMMENT '主键',
  `arrival_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '到货登记单号',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源类型：PURCHASE_ORDER、ASN、SALES_RETURN、OTHER',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源单号',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商编号',
  `supplier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商编码快照',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商名称快照',
  `inv_org_id` bigint NOT NULL COMMENT '库存组织编号',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `wh_id` bigint NOT NULL COMMENT '目标仓库编号',
  `expect_date` date NULL DEFAULT NULL COMMENT '预计到货日期',
  `arrival_time` datetime NULL DEFAULT NULL COMMENT '实际到货时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、ARRIVED、QC_PENDING、DONE、CANCELLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_arrival_no_deleted`(`arrival_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_arrival_source`(`source_type` ASC, `source_no` ASC) USING BTREE,
  INDEX `idx_wms_arrival_supplier_date`(`supplier_id` ASC, `arrival_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-到货登记' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wms_arrival
-- ----------------------------

-- ----------------------------
-- Table structure for wms_arrival_line
-- ----------------------------
DROP TABLE IF EXISTS `wms_arrival_line`;
CREATE TABLE `wms_arrival_line`  (
  `id` bigint NOT NULL COMMENT '主键',
  `arrival_id` bigint NOT NULL COMMENT '到货登记编号',
  `line_no` int NOT NULL COMMENT '行号',
  `source_line_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源单据行号',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物料规格快照',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '到货批次号',
  `supplier_lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商批次号',
  `arrival_qty` decimal(20, 6) NOT NULL COMMENT '到货数量',
  `uom_id` bigint NOT NULL COMMENT '计量单位编号',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '计量单位编码快照',
  `need_qc` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否需要质检',
  `iqc_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来料检验模式：PRE_INBOUND、POST_INBOUND_PENDING',
  `qc_task_id` bigint NULL DEFAULT NULL COMMENT '质检任务编号',
  `qualified_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '合格数量',
  `rejected_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '不合格数量',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：PENDING、QC_PENDING、READY、DONE、CANCELLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_arrival_line_no_deleted`(`arrival_id` ASC, `line_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_arrival_line_mat`(`mat_id` ASC, `lot_no` ASC) USING BTREE,
  INDEX `idx_wms_arrival_line_qc_task`(`qc_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-到货登记明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wms_arrival_line
-- ----------------------------

-- ----------------------------
-- Table structure for wms_batch
-- ----------------------------
DROP TABLE IF EXISTS `wms_batch`;
CREATE TABLE `wms_batch`  (
  `id` bigint NOT NULL COMMENT '主键',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '批次号；无批次物料使用默认批次',
  `sn_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '序列号；SN物料以数量为1的批次承载',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商编号',
  `supplier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商编码快照',
  `supplier_lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商批次号',
  `furnace_lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '炉批号',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `expiry_date` date NULL DEFAULT NULL COMMENT '失效日期',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-启用，1-停用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_batch_mat_lot_deleted`(`mat_id` ASC, `lot_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_wms_batch_sn_deleted`(`sn_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_batch_expiry_date`(`expiry_date` ASC) USING BTREE,
  INDEX `idx_wms_batch_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-批次主档' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wms_batch
-- ----------------------------

-- ----------------------------
-- Table structure for wms_command_record
-- ----------------------------
DROP TABLE IF EXISTS `wms_command_record`;
CREATE TABLE `wms_command_record`  (
  `id` bigint NOT NULL COMMENT '编号',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '幂等键，格式 sourceModule:sourceBizNo:action:sourceBizLineNo',
  `command_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '命令类型，取值见 WmsCommandTypeEnum',
  `source_module` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源模块：MES、APS、WMS、INTEGRATION、UI',
  `source_biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `source_biz_line_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源业务行号，整单命令为空',
  `result_id` bigint NULL DEFAULT NULL COMMENT '首次执行的结果编号，无返回值的命令为空',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_command_idempotency_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-跨模块命令幂等记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wms_command_record
-- ----------------------------

-- ----------------------------
-- Table structure for wms_container
-- ----------------------------
DROP TABLE IF EXISTS `wms_container`;
CREATE TABLE `wms_container`  (
  `id` bigint NOT NULL COMMENT '主键',
  `container_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '容器编号或条码',
  `type_id` bigint NOT NULL COMMENT '容器类型编号',
  `inv_org_id` bigint NOT NULL COMMENT '库存组织编号',
  `wh_id` bigint NOT NULL COMMENT '当前仓库编号',
  `loc_id` bigint NOT NULL DEFAULT 0 COMMENT '当前库位编号，0表示未落位',
  `length` decimal(20, 6) NULL DEFAULT NULL COMMENT '实际长度，单位毫米',
  `width` decimal(20, 6) NULL DEFAULT NULL COMMENT '实际宽度，单位毫米',
  `height` decimal(20, 6) NULL DEFAULT NULL COMMENT '实际高度，单位毫米',
  `gross_weight` decimal(20, 6) NULL DEFAULT NULL COMMENT '实际毛重',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'EMPTY' COMMENT '状态：EMPTY、LOADED、IN_TRANSIT、STORED、CLOSED',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_container_no_deleted`(`container_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_container_loc_status`(`loc_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_wms_container_wh_id`(`wh_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-容器主档' ROW_FORMAT = Dynamic;

