  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `batch_id` bigint NOT NULL COMMENT '批次编号',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '批次号快照',
  `loc_id` bigint NOT NULL COMMENT '库位编号',
  `loc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库位编码快照',
  `container_id` bigint NOT NULL DEFAULT 0 COMMENT '容器编号，0表示散件',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质量状态',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `book_qty` decimal(20, 6) NOT NULL COMMENT '账面数量',
  `actual_qty` decimal(20, 6) NULL DEFAULT NULL COMMENT '实盘数量',
  `diff_qty` decimal(20, 6) NULL DEFAULT NULL COMMENT '差异数量',
  `adjust_biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '差异调整入出库单号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '明细状态：PENDING、COUNTED、DIFF、ADJUSTED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_count_line_balance_deleted`(`order_id` ASC, `balance_id` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_wms_count_line_no_deleted`(`order_id` ASC, `line_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_count_line_loc`(`loc_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_wms_count_line_mat`(`mat_id` ASC, `batch_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-盘点明细' ROW_FORMAT = Dynamic;

