-- ----------------------------
-- Table structure for wms_device_task
-- ----------------------------
DROP TABLE IF EXISTS `wms_device_task`;
CREATE TABLE `wms_device_task`  (
  `id` bigint NOT NULL COMMENT '主键',
  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '本地设备任务号',
  `external_task_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '外部设备任务号',
  `task_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务类型：PUTAWAY、PICK、TRANSFER、DELIVERY、RETURN',
  `device_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备类型：WCS、AGV、RGV',
  `source_biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务类型',
  `source_biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `source_line_id` bigint NULL DEFAULT NULL COMMENT '来源业务明细编号',
  `container_id` bigint NOT NULL DEFAULT 0 COMMENT '容器编号，0表示无容器',
  `from_loc_id` bigint NOT NULL DEFAULT 0 COMMENT '来源库位编号',
  `to_loc_id` bigint NOT NULL DEFAULT 0 COMMENT '目标库位编号',
  `actual_loc_id` bigint NOT NULL DEFAULT 0 COMMENT '设备回传实际库位编号',
  `external_system_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '外部设备系统编码',
  `dispatch_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '下发状态：PENDING、SENT、FAILED',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行状态：CREATED、RUNNING、DONE、CANCELLED、EXCEPTION',
  `post_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库存过账状态：PENDING、POSTED、FAILED',
  `request_snapshot_json` json NULL COMMENT '下发业务快照',
  `callback_snapshot_json` json NULL COMMENT '完成回调快照',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务幂等键',
  `completed_time` datetime NULL DEFAULT NULL COMMENT '设备完成时间',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_device_task_no_deleted`(`task_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_wms_device_task_idem_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_wms_device_external_deleted`(`external_system_code` ASC, `external_task_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_device_task_source`(`source_biz_type` ASC, `source_biz_no` ASC) USING BTREE,
  INDEX `idx_wms_device_task_status`(`device_type` ASC, `status` ASC, `dispatch_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-设备搬运任务' ROW_FORMAT = Dynamic;

