-- ----------------------------
-- Table structure for wms_in_order_line
-- ----------------------------
DROP TABLE IF EXISTS `wms_in_order_line`;
CREATE TABLE `wms_in_order_line`  (
  `id` bigint NOT NULL COMMENT '主键',
  `order_id` bigint NOT NULL COMMENT '入库单编号',
  `line_no` int NOT NULL COMMENT '行号',
  `source_line_id` bigint NULL DEFAULT NULL COMMENT '来源明细编号',
  `source_line_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源明细行号',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物料规格快照',
  `batch_id` bigint NULL DEFAULT NULL COMMENT '批次编号，过账前可为空',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '批次号快照',
  `uom_id` bigint NOT NULL COMMENT '计量单位编号',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '计量单位编码快照',
  `loc_id` bigint NULL DEFAULT NULL COMMENT '目标库位编号',
  `loc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目标库位编码快照',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '入库质量状态',
  `plan_qty` decimal(20, 6) NOT NULL COMMENT '计划入库数量',
  `completed_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已完成数量',
  `posted_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已过账数量',
  `container_id` bigint NULL DEFAULT NULL COMMENT '容器编号',
  `qc_task_id` bigint NULL DEFAULT NULL COMMENT '质检任务编号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '明细状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_in_order_line_no_deleted`(`order_id` ASC, `line_no` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_in_order_line_mat`(`mat_id` ASC, `batch_id` ASC) USING BTREE,
  INDEX `idx_wms_in_order_line_qc_task`(`qc_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-入库单明细' ROW_FORMAT = Dynamic;

