-- ----------------------------
-- Table structure for wms_inv_balance
-- ----------------------------
DROP TABLE IF EXISTS `wms_inv_balance`;
CREATE TABLE `wms_inv_balance`  (
  `id` bigint NOT NULL COMMENT '主键',
  `inv_org_id` bigint NOT NULL COMMENT '库存组织编号',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `wh_id` bigint NOT NULL COMMENT '仓库编号',
  `loc_id` bigint NOT NULL COMMENT '库位编号',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `batch_id` bigint NOT NULL COMMENT '批次编号；无批次物料挂默认批次',
  `container_id` bigint NOT NULL DEFAULT 0 COMMENT '容器编号，0表示散件',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目归属',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务归属',
  `stock_scope` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'COMMON' COMMENT '库存范围：COMMON、PROJECT_DEDICATED',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质量状态：QUALIFIED、QC_PENDING、REJECTED、FROZEN',
  `qty_onhand` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '现存数量，基准单位',
  `qty_reserved` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '预留数量，基准单位',
  `qty_frozen` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '冻结数量，基准单位',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `mat_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物料规格快照',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '基准单位编码快照',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '批次号快照',
  `wh_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '仓库编码快照',
  `loc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库位编码快照',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_inv_balance_dimension`(`inv_org_id` ASC, `plant_id` ASC, `wh_id` ASC, `loc_id` ASC, `mat_id` ASC, `batch_id` ASC, `container_id` ASC, `project_id` ASC, `project_task_id` ASC, `stock_scope` ASC, `quality_status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_inv_balance_mat_available`(`inv_org_id` ASC, `mat_id` ASC, `quality_status` ASC, `wh_id` ASC) USING BTREE,
  INDEX `idx_wms_inv_balance_project`(`project_id` ASC, `project_task_id` ASC, `mat_id` ASC) USING BTREE,
  INDEX `idx_wms_inv_balance_container`(`container_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-多维库存余额' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wms_inv_balance
-- ----------------------------

