DROP TABLE IF EXISTS `wms_inv_lock`;
CREATE TABLE `wms_inv_lock`  (
  `id` bigint NOT NULL COMMENT '主键',
  `lock_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '冻结编号',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务类型',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `inv_org_id` bigint NOT NULL COMMENT '库存组织编号',
  `wh_id` bigint NOT NULL COMMENT '仓库编号',
  `loc_id` bigint NOT NULL COMMENT '库位编号',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `batch_id` bigint NOT NULL COMMENT '批次编号',
  `container_id` bigint NOT NULL DEFAULT 0 COMMENT '容器编号，0表示散件',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '质量状态',
  `qty` decimal(20, 6) NOT NULL COMMENT '冻结数量，基准单位',
  `released_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已解冻数量',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '冻结原因',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：ACTIVE、PARTIAL、RELEASED、CANCELLED',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '冻结幂等键',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_inv_lock_no_deleted`(`lock_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_wms_inv_lock_idempotency_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_inv_lock_biz`(`biz_type` ASC, `biz_no` ASC) USING BTREE,
  INDEX `idx_wms_inv_lock_balance`(`inv_org_id` ASC, `wh_id` ASC, `loc_id` ASC, `mat_id` ASC, `batch_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-库存冻结记录' ROW_FORMAT = Dynamic;

