  INDEX `idx_wms_inv_reservation_biz`(`biz_type` ASC, `biz_no` ASC) USING BTREE,
  INDEX `idx_wms_inv_reservation_balance`(`inv_org_id` ASC, `wh_id` ASC, `loc_id` ASC, `mat_id` ASC, `batch_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-库存预留' ROW_FORMAT = Dynamic;

