-- ----------------------------
-- Table structure for wms_inv_txn
-- ----------------------------
DROP TABLE IF EXISTS `wms_inv_txn`;
CREATE TABLE `wms_inv_txn`  (
  `id` bigint NOT NULL COMMENT '主键',
  `txn_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库存事务编号',
  `txn_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事务类型：RECEIPT、ISSUE、TRANSFER、RESERVE、RELEASE、FREEZE、UNFREEZE、QUALITY_CHANGE、ADJUST',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务类型',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源业务单号',
  `biz_line_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源业务行号',
  `io_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '收发方向：IN、OUT、MOVE、STATUS',
  `inv_org_id` bigint NOT NULL COMMENT '库存组织编号',
  `plant_id` bigint NOT NULL COMMENT '工厂编号',
  `wh_id` bigint NOT NULL COMMENT '仓库编号',
  `from_loc_id` bigint NOT NULL DEFAULT 0 COMMENT '来源库位编号，0表示无来源库位',
  `to_loc_id` bigint NOT NULL DEFAULT 0 COMMENT '目标库位编号，0表示无目标库位',
  `mat_id` bigint NOT NULL COMMENT '物料编号',
  `batch_id` bigint NOT NULL COMMENT '批次编号',
  `container_id` bigint NOT NULL DEFAULT 0 COMMENT '容器编号，0表示散件',
  `uom_id` bigint NOT NULL COMMENT '基准计量单位编号',
  `qty` decimal(20, 6) NOT NULL COMMENT '事务数量，使用正数',
  `before_qty` decimal(20, 6) NOT NULL COMMENT '过账前现存数量',
  `after_qty` decimal(20, 6) NOT NULL COMMENT '过账后现存数量',
  `quality_status_from` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更前质量状态',
  `quality_status_to` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变更后质量状态',
  `project_id_from` bigint NOT NULL DEFAULT 0 COMMENT '变更前项目编号，0表示无项目',
  `project_task_id_from` bigint NOT NULL DEFAULT 0 COMMENT '变更前项目任务编号，0表示无项目任务',
  `project_id_to` bigint NOT NULL DEFAULT 0 COMMENT '变更后项目编号，0表示无项目',
  `project_task_id_to` bigint NOT NULL DEFAULT 0 COMMENT '变更后项目任务编号，0表示无项目任务',
  `mat_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料编码快照',
  `mat_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物料名称快照',
  `uom_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '单位编码快照',
  `lot_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '批次号快照',
  `from_loc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源库位编码快照',
  `to_loc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目标库位编码快照',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '过账幂等键',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_inv_txn_no_deleted`(`txn_no` ASC, `deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_wms_inv_txn_idempotency_deleted`(`idempotency_key` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_inv_txn_biz`(`biz_type` ASC, `biz_no` ASC) USING BTREE,
  INDEX `idx_wms_inv_txn_mat_time`(`mat_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_wms_inv_txn_batch_id`(`batch_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-库存流水' ROW_FORMAT = Dynamic;

