-- Records of wms_inv_txn
-- ----------------------------

-- ----------------------------
-- Table structure for wms_loc
-- ----------------------------
DROP TABLE IF EXISTS `wms_loc`;
CREATE TABLE `wms_loc`  (
  `id` bigint NOT NULL COMMENT '主键',
  `wh_id` bigint NOT NULL COMMENT '仓库编号',
  `zone_id` bigint NOT NULL COMMENT '库区编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库位编码',
  `loc_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库位类型：ASRS_CELL、FLAT_AREA、RACK_BIN、LINE_SIDE、BLACK_BOX',
  `aisle_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '巷道号',
  `row_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '排号',
  `col_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '列号',
  `level_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '层号',
  `depth_no` int NULL DEFAULT NULL COMMENT '纵深号：双深货架专用，1-外侧靠巷道靠堆垛机，2-里侧远离堆垛机；单深货位为空',
  `max_length` decimal(20, 6) NULL DEFAULT NULL COMMENT '容器最大长度，单位毫米',
  `max_width` decimal(20, 6) NULL DEFAULT NULL COMMENT '容器最大宽度，单位毫米',
  `max_height` decimal(20, 6) NULL DEFAULT NULL COMMENT '容器最大高度，单位毫米',
  `max_weight` decimal(20, 6) NULL DEFAULT NULL COMMENT '最大承重',
  `max_volume` decimal(20, 6) NULL DEFAULT NULL COMMENT '最大容积',
  `max_container_qty` int NULL DEFAULT NULL COMMENT '最大容器数量',
  `dimension_check_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT '尺寸校验模式：NONE、HEIGHT_ONLY、FULL_DIM',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'EMPTY' COMMENT '状态：EMPTY、OCCUPIED、LOCKED、DISABLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_loc_wh_code_deleted`(`wh_id` ASC, `code` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_wms_loc_zone_status`(`zone_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'WMS-库位' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wms_loc
-- ----------------------------

-- ----------------------------
-- Table structure for wms_out_order
-- ----------------------------
DROP TABLE IF EXISTS `wms_out_order`;
CREATE TABLE `wms_out_order`  (
  `id` bigint NOT NULL COMMENT '主键',
  `out_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '出库单号',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '出库业务类型：PROD_ISSUE_OUT、SALES_DELIVERY_OUT、PO_RETURN_OUT、SCRAP_OUT、TRANSFER_OUT、COUNT_LOSS_OUT、OTHER_OUT',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '直接来源类型',
  `source_biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '直接来源业务单号',
  `source_line_id` bigint NULL DEFAULT NULL COMMENT '直接来源明细编号',
  `origin_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原始来源类型',
  `origin_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原始来源单号',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户编号',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商编号',
  `prod_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生产工单号快照',
  `work_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作业工单号快照',
  `op_task_id` bigint NULL DEFAULT NULL COMMENT '工序任务编号',
  `material_req_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '领退补料申请单号',
  `transfer_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '转移或调拨单号',
  `count_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '盘点单号',
  `inv_org_id` bigint NOT NULL COMMENT '来源库存组织编号',
  `plant_id` bigint NOT NULL COMMENT '来源工厂编号',
  `project_id` bigint NOT NULL DEFAULT 0 COMMENT '项目编号，0表示无项目',
  `project_task_id` bigint NOT NULL DEFAULT 0 COMMENT '项目任务编号，0表示无项目任务',
  `wh_id` bigint NOT NULL COMMENT '来源仓库编号',
  `wh_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源仓库编码快照',
  `to_inv_org_id` bigint NOT NULL DEFAULT 0 COMMENT '目标库存组织编号，0表示非调拨',
  `to_wh_id` bigint NOT NULL DEFAULT 0 COMMENT '目标仓库编号，0表示非调拨',
  `pick_strategy_id` bigint NULL DEFAULT NULL COMMENT '拣选策略编号',
  `hook_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT '外部设备触发方式：NONE、WCS、AGV',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、SUBMITTED、READY、TASK_CREATED、IN_PROGRESS、DONE、CANCELLED、EXCEPTION',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建幂等键',
  `biz_attrs_json` json NULL COMMENT '低频扩展属性',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注或人工原因',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_out_order_no_deleted`(`out_no` ASC, `deleted` ASC) USING BTREE,
