  `to_loc_id` bigint NULL DEFAULT NULL COMMENT '目标库位编号',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'QUALIFIED' COMMENT '要求的库存质量状态',
  `plan_qty` decimal(20, 6) NOT NULL COMMENT '计划出库数量',
  `allocated_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已分配数量',
  `picked_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已拣选数量',
  `posted_qty` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '已过账数量',
  `container_id` bigint NULL DEFAULT NULL COMMENT '容器编号',
  `reservation_id` bigint NOT NULL DEFAULT 0 COMMENT '关联库存预留编号，0表示无预留',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '明细状态',
