  `version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '策略版本号',
  `config_json` json NOT NULL COMMENT '策略条件与排序规则配置',
  `priority` int NOT NULL DEFAULT 0 COMMENT '优先级，数值越大越优先',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：DRAFT、ENABLED、DISABLED',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
